const AdmZip = require('adm-zip');
const { DOMParser } = require('@xmldom/xmldom');

const zip = new AdmZip('/workspace/testbed/docs/customer_report.docx');
const xml = zip.readAsText('word/document.xml');
const ns = 'http://schemas.openxmlformats.org/wordprocessingml/2006/main';
const doc = new DOMParser().parseFromString(xml);

function getTextFromNode(node) {
  let text = '';
  if (node.nodeType === 3) return node.nodeValue || '';
  const children = node.childNodes;
  if (!children) return '';
  for (let i = 0; i < children.length; i++) {
    const child = children[i];
    if (child.localName === 't') {
      text += child.textContent || '';
    } else if (child.localName === 'tab') {
      text += '\t';
    } else if (child.localName === 'br') {
      text += '\n';
    } else {
      text += getTextFromNode(child);
    }
  }
  return text;
}

// Get all paragraphs (including those in tables)
const bodyChildren = doc.getElementsByTagNameNS(ns, 'body')[0].childNodes;

for (let i = 0; i < bodyChildren.length; i++) {
  const node = bodyChildren[i];
  if (node.localName === 'p') {
    console.log(getTextFromNode(node));
  } else if (node.localName === 'tbl') {
    const rows = node.getElementsByTagNameNS(ns, 'tr');
    const tableData = [];
    for (let r = 0; r < rows.length; r++) {
      const cells = rows[r].getElementsByTagNameNS(ns, 'tc');
      const cellTexts = [];
      for (let c = 0; c < cells.length; c++) {
        cellTexts.push(getTextFromNode(cells[c]).trim());
      }
      tableData.push(cellTexts);
    }
    // Print as formatted table
    if (tableData.length > 0) {
      const colWidths = tableData[0].map((_, ci) => 
        Math.max(...tableData.map(row => (row[ci] || '').length))
      );
      tableData.forEach((row, ri) => {
        const line = row.map((cell, ci) => cell.padEnd(colWidths[ci])).join(' | ');
        console.log(line);
        if (ri === 0) {
          console.log(colWidths.map(w => '-'.repeat(w)).join('-+-'));
        }
      });
    }
    console.log('');
  }
}
